for the radar series could be:

    @example
    Ext.create({
       xtype: 'polar',
       renderTo: document.body,
       width: 500,
       height: 400,
       interactions: 'rotate',
       store: {
           fields: ['name', 'data1'],
           data: [{
               'name': 'metric one',
               'data1': 8
           }, {
               'name': 'metric two',
               'data1': 10
           }, {
               'name': 'metric three',
               'data1': 12
           }, {
               'name': 'metric four',
               'data1': 1
           }, {
               'name': 'metric five',
               'data1': 13
           }]
       },
       series: {
           type: 'radar',
           angleField: 'name',
           radiusField: 'data1',
