    "nth-child": function(c, a) {
        var result = [],
            m, f, i, len, n, nodeIndex;
        m = nthRe.exec(a === "even" && "2n" || a === "odd" && "2n+1" || !nthRe2.test(a) && "n+" + a || a);
        f = (m[1] || 1) - 0;
        len = m[2] - 0;
        /* eslint-disable-next-line no-cond-assign */
        for (i = 0; n = c[i]; i++) {
            nodeIndex = i + 1;
            if (f === 1) {
