    abs: function(arg) {
        return Math.abs(arg);
    },
    'avg...': function(args) {
        var count = 0,
            sum = 0,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                sum += v;
                ++count;
            }
        }
        return count ? sum / count : 0;
    },
    date: function(arg) {
        return (arg instanceof Date) ? arg : Ext.Date.parse(arg);
    },
    lower: function(arg) {
        return (arg == null) ? '' : String(arg).toLowerCase();
    },
    'max...': function(args) {
        var ret = null,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                ret = (ret === null) ? v : (ret < v ? v : ret);
            }
        }
        return ret;
    },
    'min...': function(args) {
        var ret = null,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                ret = (ret === null) ? v : (ret < v ? ret : v);
            }
        }
        return ret;
    },
    'sum...': function(args) {
        var ret = null,
            i = args.length,
            v;
        for (; i-- > 0; /* empty */
        ) {
            v = args[i];
            if (v != null) {
                ret = (ret === null) ? v : (ret + v);
            }
        }
        return ret === null ? 0 : ret;
    },
