items.text:
Object hash of "pseudo class" filter functions which are used when filtering selections.
Each function is passed two parameters:

- **c** : Array
    An Array of DOM elements to filter.

- **v** : String
    The argument (if any) supplied in the selector.

A filter function returns an Array of DOM elements which conform to the pseudo class.
In addition to the provided pseudo classes listed above such as `first-child` and
`nth-child`, developers may add additional, custom psuedo class filters to select
elements according to application-specific requirements.

For example, to filter `a` elements to only return links to __external__ resources:

    Ext.DomQuery.pseudos.external = function(c, v) {
        var r = [], ri = -1;
        for(var i = 0, ci; ci = c[i]; i++) {
            // Include in result set only if it's a link to an external resource
            if (ci.hostname != location.hostname) {
                r[++ri] = ci;
            }
        }
        return r;
    };

Then external links could be gathered with the following statement:

    var externalLinks = Ext.select("a:external");

items.value:
{
    "first-child": function(c) {
        var r = [],
            ri = -1,
            n, i, ci;
        for (i = 0; (ci = n = c[i]); i++) {
            while ((n = n.previousSibling) && n.nodeType != 1) {}
            // This block is intentionally left blank
            if (!n) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "last-child": function(c) {
        var r = [],
            ri = -1,
            n, i, ci;
        for (i = 0; (ci = n = c[i]); i++) {
            while ((n = n.nextSibling) && n.nodeType != 1) {}
            // This block is intentionally left blank
            if (!n) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "nth-child": function(c, a) {
        var r = [],
            ri = -1,
            m = nthRe.exec(a == "even" && "2n" || a == "odd" && "2n+1" || !nthRe2.test(a) && "n+" + a || a),
            // eslint-disable-line max-len
            f = (m[1] || 1) - 0,
            l = m[2] - 0,
            i, n, j, cn, pn;
        for (i = 0; n = c[i]; i++) {
            pn = n.parentNode;
            if (batch != pn._batch) {
                j = 0;
                for (cn = pn.firstChild; cn; cn = cn.nextSibling) {
                    if (cn.nodeType == 1) {
                        cn.nodeIndex = ++j;
                    }
                }
                pn._batch = batch;
            }
            if (f == 1) {
                if (l === 0 || n.nodeIndex == l) {
                    r[++ri] = n;
                }
            } else if ((n.nodeIndex + l) % f === 0) {
                r[++ri] = n;
            }
        }
        return r;
    },
    "only-child": function(c) {
        var r = [],
            ri = -1,
            i, ci;
        for (i = 0; ci = c[i]; i++) {
            if (!prev(ci) && !next(ci)) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "empty": function(c) {
        var r = [],
            ri = -1,
            i, ci, cns, j, cn, empty;
        for (i = 0; ci = c[i]; i++) {
            cns = ci.childNodes;
            j = 0;
            empty = true;
            while (cn = cns[j]) {
                ++j;
                if (cn.nodeType == 1 || cn.nodeType == 3) {
                    empty = false;
                    break;
                }
            }
            if (empty) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "contains": function(c, v) {
        var r = [],
            ri = -1,
            i, ci;
        for (i = 0; ci = c[i]; i++) {
            if ((ci.textContent || ci.innerText || ci.text || '').indexOf(v) != -1) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "nodeValue": function(c, v) {
        var r = [],
            ri = -1,
            i, ci;
        for (i = 0; ci = c[i]; i++) {
            if (ci.firstChild && ci.firstChild.nodeValue == v) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "checked": function(c) {
        var r = [],
            ri = -1,
            i, ci;
        for (i = 0; ci = c[i]; i++) {
            if (ci.checked === true) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "not": function(c, ss) {
        return DQ.filter(c, ss, true);
    },
    "any": function(c, selectors) {
        var ss = selectors.split('|'),
            r = [],
            ri = -1,
            s, i, ci, j;
        for (i = 0; ci = c[i]; i++) {
            for (j = 0; s = ss[j]; j++) {
                if (DQ.is(ci, s)) {
                    r[++ri] = ci;
                    break;
                }
            }
        }
        return r;
    },
    "odd": function(c) {
        return this["nth-child"](c, "odd");
    },
    "even": function(c) {
        return this["nth-child"](c, "even");
    },
    "nth": function(c, a) {
        return c[a - 1] || [];
    },
    "first": function(c) {
        return c[0] || [];
    },
    "last": function(c) {
        return c[c.length - 1] || [];
    },
    "has": function(c, ss) {
        var s = DQ.select,
            r = [],
            ri = -1,
            i, ci;
        for (i = 0; ci = c[i]; i++) {
            if (s(ss, ci).length > 0) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "next": function(c, ss) {
        var is = DQ.is,
            r = [],
            ri = -1,
            i, ci, n;
        for (i = 0; ci = c[i]; i++) {
            n = next(ci);
            if (n && is(n, ss)) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    "prev": function(c, ss) {
        var is = DQ.is,
            r = [],
            ri = -1,
            i, ci, n;
        for (i = 0; ci = c[i]; i++) {
            n = prev(ci);
            if (n && is(n, ss)) {
                r[++ri] = ci;
            }
        }
        return r;
    },
    focusable: function(candidates) {
        var len = candidates.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = candidates[i];
            if (Ext.fly(c, '_DomQuery').isFocusable()) {
                results.push(c);
            }
        }
        return results;
    },
    visible: function(candidates, deep) {
        var len = candidates.length,
            results = [],
            i = 0,
            c;
        for (; i < len; i++) {
            c = candidates[i];
            if (Ext.fly(c, '_DomQuery').isVisible(deep)) {
                results.push(c);
            }
        }
        return results;
    },
    isScrolled: function(c) {
        var r = [],
            ri = -1,
            i, ci, s;
        for (i = 0; ci = c[i]; i++) {
            s = Ext.fly(ci, '_DomQuery').getScroll();
            if (s.top > 0 || s.left > 0) {
                r[++ri] = ci;
            }
        }
        return r;
    }
}

(function() {
    var property = 'boxShadow',
        style = document.documentElement.style;
    if (!('boxShadow' in style)) {
        if ('WebkitBoxShadow' in style) {
            // Safari prior to version 5.1 and Chrome prior to version 10
            property = 'WebkitBoxShadow';
        } else if ('MozBoxShadow' in style) {
