    Ext.create('Ext.panel.Panel', {
        width: 200,
        height: 200,
        renderTo: document.body,
        title: 'A Panel',
        tools: [{
            type: 'help',
            callback: function() {
                // show help here
            }
        }, {
            itemId: 'reply',
            glyph: 'xf112@FontAwesome', // Reply icon
            hidden: true,
            callback: function() {
